import React, { useState } from 'react';
import './EnquiryForm.css';

const EnquiryForm = () => {
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [mobile, setMobile] = useState('');
    const [city, setCity] = useState('');
    const [option, setOption] = useState('');
    const [query, setQuery] = useState('');

    const handleNameChange = (e) => {
        setName(e.target.value);
    };

    const handleEmailChange = (e) => {
        setEmail(e.target.value);
    };

    const handleMobileChange = (e) => {
        setMobile(e.target.value);
    };

    const handleCityChange = (e) => {
        setCity(e.target.value);
    };

    const handleOptionChange = (e) => {
        setOption(e.target.value);
    };

    const handleQueryChange = (e) => {
        setQuery(e.target.value);
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        console.log('Form submitted:', { name, email, mobile, city, option, query });

        setName('');
        setEmail('');
        setMobile('');
        setCity('');
        setOption('');
        setQuery('');
    };

    return (
        <form className="enquiry-form w-[300px] md:w-[450px] py-10 rounded-xl bg-indigo-40 bg-black bg-opacity-60" onSubmit={handleSubmit}>
            <div className="form-group">
                <label>Full Name <span>*</span></label>
                <input type="text" value={name} onChange={handleNameChange} placeholder='Enter Your Name' required />
            </div>
            <div className="form-group">
                <label>Email <span>*</span></label>
                <input type="email" value={email} onChange={handleEmailChange} placeholder='Your Email' required />
            </div>
            <div className="form-group">
                <label>Mobile Number <span>*</span></label>
                <input type="tel" value={mobile} onChange={handleMobileChange} placeholder='Your Mobile number' required />
            </div>
            <div className="form-group">
                <label>City <span>*</span></label>
                <input type="text" value={city} onChange={handleCityChange} placeholder='Your City' required />
            </div>
            <div className="form-group">
                <label>Category <span>*</span></label>
                <select value={option} onChange={handleOptionChange} required>
                    <option value="">Select an option</option>
                    <option value="foundation">Foundation</option>
                    <option value="boards">Boards</option>
                    <option value="jee">JEE</option>
                    <option value="neet">NEET</option>
                    <option value="target">Target</option>
                </select>
            </div>
            <div className="form-group">
                <label>Query <span>*</span></label>
                <textarea value={query} onChange={handleQueryChange} placeholder='Your Message' required />
            </div>
            <button type="submit">Submit</button>
        </form>
    );
};

export default EnquiryForm;
